contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        uint beforeContractBal = address(c).balance;
        uint beforeTestBal = address(this).balance;

        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        uint midContractBal = address(c).balance;
        uint midTestBal = address(this).balance;
        uint creditBefore = midContractBal - beforeContractBal;

        bool success;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            success = false;
        } else {
            success = true;
        }

        uint afterContractBal = address(c).balance;
        uint afterTestBal = address(this).balance;

        assert(success ? (afterContractBal == midContractBal - creditBefore && afterTestBal == midTestBal + creditBefore) : (afterContractBal == midContractBal && afterTestBal == midTestBal));
    }

    receive() external payable {}
}

