// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint beforeContractBal = address(c).balance;
        uint beforeTestBal = address(this).balance;
        try c.deposit{value: amount}() {} catch { return; }
        uint midContractBal = address(c).balance;
        uint midTestBal = address(this).balance;
        uint creditBefore = midContractBal - beforeContractBal;
        bool success;
        try c.withdrawAll() {
            success = true;
        } catch {
            success = false;
        }
        uint afterContractBal = address(c).balance;
        uint afterTestBal = address(this).balance;
        assertTrue(success ? (afterContractBal == midContractBal - creditBefore && afterTestBal == midTestBal + creditBefore) : (afterContractBal == midContractBal && afterTestBal == midTestBal));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
